/**
 * The types `data/daily-missions/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    DailyMissionTierReward, DailyMissionWeeklyReward, DailyMissionLabLevel
 * depends    —
 * used by    src/data/daily-missions/data, src/data/daily-missions/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from data.ts

export interface DailyMissionTierReward {
  tier: number
  coins: string
  shards: string
}

export interface DailyMissionWeeklyReward {
  missionsCompleted: number
  coinsMultiplier: string
  gems: number
  medals: number
  stones: number
  tokens: number
}

export interface DailyMissionLabLevel {
  level: number
  time: string
  cost: string
  value: string
}
